open(F, "w", encoding="utf-8").write(out)

# report
def body_words(t):
    ai = t.find("**Objective.**")
    ci = t.find("**Conclusions.**", ai)
    tail = t[ci:]; em = re.search(r"\n---", tail)
    ae = ci + (em.start() if em else len(tail))
    leg = t.find("## Figure legends")
    body = t[ae:leg]
    body = "\n".join(l for l in body.splitlines() if not l.strip().startswith("|"))
    return len(re.findall(r"[A-Za-z][A-Za-z0-9'\-]*", body))

print("NEW main body words:", body_words(out))
print("Replaced", len(repl), "lines.")
